/* Hairline — generated by NoaCG Studio. Edit freely: this file is yours. */

/* ── Style contract: change these variables to retint the whole graphic. ── */
:root {
  --accent: #e8c547;           /* the one accent color */
  --text-color: #ffffff;          /* primary text */
  --text-dim: rgba(255,255,255,0.72);  /* secondary text (title line) */
  --panel-bg: rgba(12, 14, 18, 0.92);  /* the panel behind the text */
  --font-heading: "Inter", Arial, sans-serif;  /* the graphic's typeface */
  --scale: 1;                  /* whole-graphic size multiplier (also handles resolution) */
  --type-scale: 1;                  /* text-only size multiplier (on top of --scale) */
  --accent-weight: calc(3px * var(--scale));    /* thickness of the accent bar */
  --display-weight: 700;                        /* heading weight */
  --display-tracking: -0.01em;                  /* heading letter-spacing (big text tightens) */
}

/* Bundled open-source font (the file ships with the export — no internet at playout). */
@font-face {
  font-family: "Inter";
  src: url("fonts/inter.woff2") format("woff2");
  font-weight: 400 800;  /* variable font: covers this weight range */
  font-display: swap;          /* show fallback text until the font loads */
}

/* Reset and a transparent canvas (broadcast graphics render over video). */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;                /* nothing ever scrolls on air */
  background: transparent;
  font-family: var(--font-heading);
}

/* ── Root position (anchor zone) ── */
.lower-third {
  position: absolute;
  left: 120px;                     /* inset from the left edge (safe area) */
  bottom: 119px;                   /* inset from the bottom — wrapped text grows upward */
  text-align: left;                /* lines align toward the anchor edge */
  opacity: 0;                      /* hidden until play() runs the entrance */
}

/* ── Auto-fit: the panel hugs its text and wraps instead of overflowing. ── */
.lower-third-box {
  width: fit-content;              /* the panel hugs the text */
  max-width: 1680px;  /* fallback: no CSS min() before Chromium 79 (older CasparCG) */
  max-width: min(calc(806px * var(--scale)), 1680px);  /* the wrap cap — follows --scale, stops at the safe area */
  will-change: transform, opacity; /* hint the browser: this element animates */
}
.lower-third-mask {
  overflow: hidden;                /* lines animate in from behind this mask */
}
.lower-third-mask > span {
  display: inline-block;           /* so the line can move inside its mask */
  overflow-wrap: anywhere;         /* a word too long for its mask breaks: break-word cannot narrow the line, so the mask cut its end off */
  text-wrap: balance;              /* wrapped rows get even lengths */
}

/* ── Design ── */
/* The hairline — a thin vertical line spanning the full height of the text block.
   It is the design's only non-text element; presets grow it in via transform. */
.lower-third-accent {
  position: absolute;               /* pinned inside the positioned .lower-third root */
  left: 0;                          /* sits at the block's left edge */
  top: 0;                           /* stretches from the very top… */
  bottom: 0;                        /* …to the very bottom of the text block */
  width: var(--accent-weight);      /* the family's accent-line weight */
  background: var(--accent);        /* the one small, sharp dose of accent color */
  will-change: transform;           /* hint the browser: presets animate this line */
}

/* The text block — deliberately transparent: no panel, whitespace does the work. */
.lower-third-box {
  padding-left: calc(27px * var(--scale));  /* room for the 3px line + a generous 24px gap */
}

/* Name line — big and confident; the only heavy element in the design. */
.lower-third-name {
  font-size: calc(54px * var(--scale) * var(--type-scale));  /* headline size (values are 1080p reference) */
  font-weight: var(--display-weight);  /* the family's display weight */
  line-height: 1.08;                /* big text sits tight */
  letter-spacing: var(--display-tracking);  /* large display type tightens slightly */
  color: var(--text-color);         /* primary text color */
}

/* Title line (and any extra line) — quiet on purpose: smaller, lighter, dimmed. */
.lower-third-title,
.lower-third-extra {
  font-size: calc(24px * var(--scale) * var(--type-scale));  /* ≈2.2:1 below the name — clear hierarchy */
  font-weight: 400;                 /* regular weight; contrast comes from the name */
  line-height: 1.3;                 /* secondary text gets room to breathe */
  color: var(--text-dim);           /* dimmed — never pure white twice */
  margin-top: calc(6px * var(--scale));  /* small gap: name + title read as one unit */
}

