  "root": ".lower-third",
  "speed": 1,
  "steps": [
    {
      "name": "Enter",
      "duration": 1.34,
      "ease": "expo.out",
      "layers": {
        ".lower-third-accent": {
          "scaleX": [
            { "time": 0, "value": 0 },
            { "time": 0.6, "value": 1 }
