            { "time": 0.5, "value": 110 },
            { "time": 1.2, "value": 0 }
          ]
        },
        "#f1": {
          "yPercent": [
            { "time": 0.64, "value": 110 },
            { "time": 1.34, "value": 0 }
          ]
        }
      }
    },
    {
      "name": "Out",
      "duration": 0.75,
      "ease": "power3.in",
      "layers": {
        "#f0": {
          "yPercent": [
            { "time": 0, "value": 0 },
            { "time": 0.35, "value": 110 }
