  return rejoin ? noacgFire(main, rejoin) : null;
}

// Process one queued entry. Timer firings re-check their arming state — the graphic may have
// moved while they sat in the queue — so a stale timer is dropped, never misfired.
function noacgProcessOne(e) {
  if (e.timerGroup) {
    for (var g = 0; g < noacgMachine.groups.length; g++) {
      var tg = noacgMachine.groups[g];
      if (tg.id !== e.timerGroup) continue;
      if (noacgCurrent[tg.id] !== e.from) return null;
      var timerEdge = noacgTimerEdge(tg, e.from);
      return timerEdge ? noacgFire(tg, timerEdge) : null;
    }
    return null;
  }
  if (e.pathStep) return noacgProcessNext();
  if (!NOACG_ANIM.machine) {
    // Machine-less templates keep the classic playback exactly; 'next' is their one event.
    return e.event === 'next' ? revealNextStep() : null;
  }
  // Structural guarding: only groups whose CURRENT state has an arrow for this event fire —
  // several may (parallel groups), none means the event is illegal right now and is dropped.
  var firing = [];
  for (var g2 = 0; g2 < noacgMachine.groups.length; g2++) {
    var group = noacgMachine.groups[g2];
    var edge = noacgOperatorEdge(group, noacgCurrent[group.id], e.event);
    if (edge) firing.push({ group: group, edge: edge });
  }
  if (firing.length === 0) return null;
  if (!noacgSoundCanExecute()) return null;
  if (e.payload) noacgApplyPayload(e.payload);
  var last = null;
  for (var f = 0; f < firing.length; f++) {
    var tl = noacgFire(firing[f].group, firing[f].edge);
    if (tl) last = tl;
  }
  return last;
}

// noacgDispatch(event, payload?): send one operator event through the SERIAL queue. Events
// resolve one at a time in arrival order — near-simultaneous events and multi-part updates
// land deterministically and atomically. The optional payload is a flat {field: value} map
// applied only when the event is accepted. Returns the last timeline the event started
// (null when guarded out or queued behind a running drain).
function noacgDispatch(event, payload) {
  noacgQueue.push(typeof event === 'string' ? { event: event, payload: payload } : event);
  if (noacgDraining) return null;
  noacgDraining = true;
  var last = null;
  while (noacgQueue.length > 0) {
    var tl = noacgProcessOne(noacgQueue.shift());
    if (tl) last = tl;
  }
  noacgDraining = false;
  return last;
}

// play() under a machine: the built-in reset-and-enter — every group to its initial state,
// the queue cleared, the entrance played, the first waypoint's timer armed. A STYLE on the
// materialised play edge (cut/fade/push/wipe) plays the styled change instead of the
// entrance timeline, landing on the same settled pose (the swap composes the pointers'
// pose, set below before the timeline runs).
function noacgMachinePlay() {
  noacgCancelAllTimers();
  noacgQueue.length = 0;
  noacgGroupTl = {};
  noacgResetPointers();
  noacgStepsPlayed = 1;
  var main = noacgMachine.groups[0];
  noacgCurrent[main.id] = (main.defaultPath || [])[0];
  var edge = noacgLifecycleEdge('play');
  var tl = (edge && edge.style !== undefined ? noacgStyleTimeline(main, edge) : null) || noacgEntranceTimeline();
  noacgSoundStart((edge && edge.sound) || NOACG_ANIM.steps[0].sound, main.id);
  noacgGroupTl[main.id] = tl;
  noacgArmTimer(main, noacgCurrent[main.id], tl);
  return tl;
}

function noacgMachineNext() {
  return noacgDispatch({ pathStep: true });
}

// stop() under a machine: the built-in out — legal from every state, cancels timers, flushes
// the queue, plays the exit, and rests every group at its initial state. A STYLE on the
// materialised stop edge plays the styled change instead of the Out timeline, from WHEREVER
// the graphic is: the pointers rest first, so the swap composes the off pose — and the Out
// step's lifecycle calls still run once at the swap (a clock's stopClock must not be skipped
// just because the exit was styled).
function noacgMachineStop() {
  noacgSoundStopAll();
  noacgCancelAllTimers();
  noacgQueue.length = 0;
  var edge = noacgLifecycleEdge('stop');
  var styled = edge && edge.style !== undefined ? noacgStyleTimeline(noacgMachine.groups[0], edge) : null;
  var tl = styled || noacgExitTimeline();
  noacgSoundExecute((edge && edge.sound) || NOACG_ANIM.steps[NOACG_ANIM.steps.length - 1].sound, noacgMachine.groups[0].id, tl, !!(edge && edge.sound));
  noacgGroupTl = {};
  noacgResetPointers();
  return tl;
}

// The canonical route to a state: for a main-group waypoint, the default-path prefix; else
// BFS shortest path from the group's initial over authored operator/timer arrows
// (data-condition never fires) plus the walk's own edges, ties resolved by declaration
// order. Mirrors blocks/animMachine.ts canonicalPath — keep them in agreement.
function noacgCanonicalPath(group, targetId) {
  if (targetId === group.initial) return [];
  var isMain = group === noacgMachine.groups[0];
  var path = group.defaultPath || [];
  if (isMain) {
    var pi = noacgPathIndex(targetId);
    if (pi >= 0) return path.slice(0, pi + 1);
  }
  var edges = [];
  if (isMain && path.length > 0) {
    edges.push({ from: group.initial, to: path[0] });
    for (var w = 0; w + 1 < path.length; w++) edges.push({ from: path[w], to: path[w + 1] });
  }
  for (var i = 0; i < group.transitions.length; i++) {
    if (group.transitions[i].trigger !== 'data-condition') edges.push(group.transitions[i]);
  }
  var cameFrom = {};
  var seen = {};
  seen[group.initial] = true;
  var queue = [group.initial];
  while (queue.length > 0) {
    var at = queue.shift();
    for (var e = 0; e < edges.length; e++) {
      var edge = edges[e];
      if (edge.from !== at || seen[edge.to]) continue;
      seen[edge.to] = true;
      cameFrom[edge.to] = at;
      if (edge.to === targetId) {
        var route = [];
        var id = targetId;
        while (id !== group.initial) { route.unshift(id); id = cameFrom[id]; }
        return route;
      }
      queue.push(edge.to);
    }
  }
  return null;
}

// Return the graphic to its CSS rest: clear every inline style the animations wrote.
// Self-contained (no editor needed), so snap works identically in exports.
function noacgResetGraphic() {
  if (noacgOutTimeline) noacgOutTimeline.kill();
  noacgOutTimeline = null;
  noacgLiveTimeline = null;
  var root = document.querySelector(NOACG_ANIM.root);
  if (root) {
    gsap.set(root, { clearProps: 'all' });
    var all = root.querySelectorAll('*');
    for (var i = 0; i < all.length; i++) gsap.set(all[i], { clearProps: 'all' });
  }
  // clearProps wipes INLINE styles, and one of them is not the animation's to wipe: an image
  // field with no picture is hidden inline (setFieldValue removes the src and sets
  // display:none), so clearing it turns an empty field into a 52px broken-image box on air.
  // Re-hide every srcless field image — the data layer's truth, restated after the reset.
  var imgs = document.querySelectorAll('img[id]');
  for (var m = 0; m < imgs.length; m++) {
    if (!imgs[m].getAttribute('src')) imgs[m].style.display = 'none';
  }
  // Press-revealed layers can sit OUTSIDE the root — clear them too.
  for (var s = 1; s < NOACG_ANIM.steps.length - 1; s++) {
    var reveals = NOACG_ANIM.steps[s].reveals || [];
    for (var r = 0; r < reveals.length; r++) {
      var el = document.querySelector(reveals[r]);
      if (el) gsap.set(el, { clearProps: 'all' });
    }
  }
}

// noacgSnap(assignments, opts?): enter states INSTANTLY — no animation replay. assignments
// is a {groupId: stateId} map; groups not named keep their current state; null means every
// group to its initial — the VISUAL half of reset (data reset stays update()'s job, the two
// are never conflated). The pose is composed by replaying each group's canonical path with
// suppressed callbacks, so clocks, loops and timers stay silent during composition. Entry
// timers then arm by default (recovery: a snapped-into ticker resumes cycling); pass
// { timers: false } to park the graphic (the editor's preview does).
function noacgSnap(assignments, opts) {
  opts = opts || {};
  var want = {};
  var g, group;
  for (g = 0; g < noacgMachine.groups.length; g++) {
    group = noacgMachine.groups[g];
    var target = assignments === null || assignments === undefined
      ? group.initial
      : (assignments[group.id] !== undefined ? assignments[group.id] : noacgCurrent[group.id]);
    if (!noacgStateOf(group, target)) target = group.initial;
    want[group.id] = target;
  }
  Object.keys(noacgSoundPlaying).forEach(function (key) {
    var p = noacgSoundPlaying[key];
    if (p.sound.mode !== 'loop' || opts.timers === false || noacgCurrent[p.group] !== want[p.group]) noacgSoundStop(key);
  });
  noacgCancelAllTimers();
  noacgQueue.length = 0;
  gsap.killTweensOf('*');
  noacgGroupTl = {};
  noacgResetGraphic();
  noacgStepsPlayed = 0;
  noacgResetPointers();
  for (g = 0; g < noacgMachine.groups.length; g++) {
    group = noacgMachine.groups[g];
    if (want[group.id] === group.initial) continue;
    var route = noacgCanonicalPath(group, want[group.id]);
    if (!route) continue; // unreachable — the group rests at its initial state
    for (var s = 0; s < route.length; s++) {
      var tl = noacgEnterTimeline(group, route[s]);
      if (tl) { tl.pause(0); tl.progress(1, true); tl.kill(); }
      noacgCurrent[group.id] = route[s];
      if (group === noacgMachine.groups[0]) {
        var idx = noacgPathIndex(route[s]);
        if (idx >= 0) noacgStepsPlayed = idx + 1;
      }
    }
    noacgFireCalls(noacgStepFor(group, want[group.id])); // the target state's own effects
    if (opts.timers !== false) noacgArmTimer(group, want[group.id], null);
  }
  if (opts.timers !== false) noacgSoundRestore();
  return noacgMachineState();
}

// A copy of the machine's pointers — for tests, the editor's state chip, and recovery.
function noacgMachineState() {
  var out = { groups: {} };
  for (var g = 0; g < noacgMachine.groups.length; g++) {
    var id = noacgMachine.groups[g].id;
    out.groups[id] = noacgCurrent[id];
  }
  return out;
}
// Decode ahead of readiness; errors are retained for warm/load and never cause a cue-time fetch.
noacgSoundPrepare().catch(function (e) { console.error(String(e.message || e)); });

/* == END ANIMATION == */

/* == LIVE DATA (published CSV → update) — edit or delete this whole block == */
// Publish your sheet: File → Share → Publish to web → (sheet) → CSV, and paste the link below.
(function () {
  var CSV_URL = "https://docs.google.com/spreadsheets/d/e/2PACX-fixture/pub?output=csv";
  var POLL_MS = 5000;

  // Which sheet column feeds which field. The header name must match your sheet's first row.
  var MAP = {
    "f0": "Name",   // ← sheet column header
    "f1": "Title",   // ← sheet column header
  };
  // Which data row to read (0 = the first row AFTER the header). Change for multi-row sheets.
  var ROW = 0;

  // Minimal CSV parser (handles quoted cells with commas / quotes).
  function parseCsv(text) {
    var rows = [], row = [], cell = '', q = false;
    for (var i = 0; i < text.length; i++) {
      var c = text[i];
      if (q) {
        if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; }
        else if (c === '"') q = false;
        else cell += c;
      } else if (c === '"') q = true;
      else if (c === ',') { row.push(cell); cell = ''; }
      else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
      else cell += c;
    }
    if (cell.length || row.length) { row.push(cell); rows.push(row); }
    return rows;
  }

  function pull() {
    fetch(CSV_URL, { cache: 'no-store' }).then(function (r) { return r.text(); }).then(function (text) {
      var rows = parseCsv(text);
      var headers = rows[0] || [];
      var data = rows[ROW + 1] || [];
      var out = {};
      for (var field in MAP) {
        var col = headers.indexOf(MAP[field]);
        if (col >= 0) out[field] = data[col];
      }
      if (typeof update === 'function') update(JSON.stringify(out));
    }).catch(function () { /* offline or CORS-blocked — see the note above; the graphic still runs */ });
  }

  pull();
  setInterval(pull, POLL_MS);
})();
/* == END LIVE DATA == */

template.css:
/* News Strip — generated by NoaCG Studio. Edit freely: this file is yours. */

/* ── Style contract: change these variables to retint the whole graphic. ── */
:root {
  --accent: #e63946;           /* the one accent color */
  --text-color: #ffffff;          /* primary text */
  --text-dim: rgba(255,255,255,0.7);  /* secondary text (title line) */
  --panel-bg: rgba(10, 12, 16, 0.92);  /* the panel behind the text */
  --font-heading: "Inter", Arial, sans-serif;  /* the graphic's typeface */
  --scale: 1;                  /* whole-graphic size multiplier (also handles resolution) */
  --type-scale: 1;                  /* text-only size multiplier (on top of --scale) */
  --accent-weight: calc(3px * var(--scale));    /* thickness of the accent bar */
  --label-tracking: 0.12em;                     /* label letter-spacing (small caps breathe) */
}

/* Bundled open-source font (the file ships with the export — no internet at playout). */
@font-face {
  font-family: "Inter";
  src: url("fonts/inter.woff2") format("woff2");
  font-weight: 400 800;  /* variable font: covers this weight range */
  font-display: swap;          /* show fallback text until the font loads */
}

/* Reset and a transparent canvas (broadcast graphics render over video). */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;                /* nothing ever scrolls on air */
  background: transparent;
  font-family: var(--font-heading);
}

/* ── Root position (anchor zone) ── */
.ticker {
  position: absolute;
  left: calc(50% + 0px);           /* anchored to the horizontal center */
  bottom: 119px;                   /* inset from the bottom — wrapped text grows upward */
  transform: translateX(-50%);     /* center on the anchor point */
  text-align: center;              /* lines align toward the anchor edge */
  opacity: 0;                      /* hidden until play() runs the entrance */
}

/* ── Item kicker: the tag a story is filed under ("SPORT: United win 3-0"). ──
   Shared, and emitted BEFORE the design so a design that wants its own treatment simply
   restates the rule. Every ticker gets one for free, which is what makes the mark portable:
   the same rundown carries its tags into whichever design you switch to. */
.ticker-kicker {
  color: var(--accent);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-right: calc(10px * var(--scale));
}

/* ── Design ── */
/* The strip: a full-width dark bar; the accent top border is the lt02 underline motif. */
.ticker-box {
  display: flex;                   /* label left, viewport filling the rest */
  align-items: stretch;            /* the label block spans the full strip height */
  width: calc(1680px * var(--scale));  /* near full-width, inside the safe areas */
  height: calc(90px * var(--scale));   /* the strip's fixed height */
  overflow: hidden;                /* nothing paints past the band - a ticker runs full-bleed
                                      or carries EQUAL margins, never one (the owner rule the
                                      2026-08-19 read restated on this design) */
  background: var(--panel-bg);     /* near-black bar — never pure #000 */
  border-top: var(--accent-weight) solid var(--accent);  /* the strip's authored accent weight */
  will-change: opacity;            /* hint the browser: the preset fades this */
}

/* The label block — solid accent, light ink. The family's accent-ink (the panel hue) sat on
   the signal red at 4.46:1 and the 2026-08-19 blind read failed it twice in the same words:
   "red background, black text - I don't think that works". White on that red is the newsroom
   convention (every BREAKING band), and at this size and weight it clears the large-text
   floor. The block is also BOUNDED: an operator label longer than a third of the strip trims
   with an ellipsis instead of displacing the viewport out of the band. */
.ticker-label {
  display: flex;                   /* center the label text inside the block */
  align-items: center;             /* vertical centering */
  flex-shrink: 0;                  /* never squeezed by the scrolling viewport */
  max-width: calc(560px * var(--scale));  /* a label is a tag - it never becomes the strip */
  padding: 0 calc(35px * var(--scale));  /* generous horizontal breathing room */
  background: var(--accent);       /* the one solid accent surface */
  font-size: calc(24px * var(--scale) * var(--type-scale)); /* kicker scale — clear of the size warning band */
  font-weight: 700;                /* bold so the small caps carry */
  letter-spacing: var(--label-tracking);  /* the label block's authored tracking */
  text-transform: uppercase;       /* reads as a tag, whatever the operator types */
  color: var(--text-color);        /* light ink on the accent block - the read's ruling */
}

/* The label text itself: one line, trimmed with an ellipsis past the block's cap. */
.ticker-label > span {
  overflow: hidden;                /* everything past the cap is cut... */
  text-overflow: ellipsis;         /* ...and the cut is marked */
  white-space: nowrap;             /* a tag is one line, whatever is typed into it */
}

/* The scrolling window — items travel through it and clip at its edges. */
.ticker-viewport {
  flex-grow: 1;                    /* take all the strip width the label leaves */
  overflow: hidden;                /* the marquee window — items vanish at the edges */
  display: flex;                   /* so the track can be vertically centered */
  align-items: center;             /* items sit on the strip's centerline */
}

/* The track — one endless row of items; the marquee preset slides its x. */
#ticker-track {
  display: inline-flex;            /* items in a single row, width = content */
  align-items: center;             /* items and separators share a baseline zone */
  white-space: nowrap;             /* never wrap — the track is one continuous line */
  will-change: transform;          /* the marquee animates x every frame */
}

/* One news item — quiet, readable, subordinate to nothing. */
.ticker-item {
  font-size: calc(28px * var(--scale) * var(--type-scale)); /* comfortable reading size at travel speed */
  font-weight: 500;                /* a touch of presence without shouting */
  color: var(--text-color);        /* primary text color */
}

/* The dot between items — dimmed punctuation, never a second accent. */
.ticker-sep {
  margin: 0 calc(35px * var(--scale)); /* even air on both sides of the dot */
  font-size: calc(20px * var(--scale) * var(--type-scale)); /* small — a pause, not a bullet point */
  color: var(--text-dim);          /* dimmed so the items stay the focus */
}


/* Hidden data sources — holders SPX writes into and the runtime reads, never drawn.
   The rule lives in the stylesheet on purpose: an inline display:none would be wiped by the
   editor's entrance reset (it clears inline props) and the value would appear on screen. */
.noacg-data-source {
  display: none;                   /* input only: written by SPX, read by JS, never rendered */
}

template.js:
// News Strip — generated by NoaCG Studio. SPX calls update(), play(), stop(), next().

// escapeHtml(): rows below are built with innerHTML — operator text is escaped first, so
// input like "Team <3" reads as text and never runs as markup.
function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// parseTickerItems(text): the rundown is ONE block of plain text, and there is one mark to
// learn - A COLON ENDS A KICKER. Everything else is the story.
//
//   SPORT: United win 3-0     a story TAGGED with what it is about. The tag is the kicker.
//   SPORT:                    a kicker on its own line. Every story beneath it carries it,
//   United win 3-0            until a blank line or the next kicker - so a run of stories
//   City held at home         from one desk is typed once, not once per line.
//   SPORT <TAB> United win    the same, which is what a paste from a spreadsheet gives.
//   Storm warning issued      anything else is a plain story, with no kicker at all.
//   (blank line)              closes the open kicker.
//
// A semicolon is accepted wherever a colon is, for the same reason end credits accept one.
//
// NO PIPE, and that is a deliberate difference from docs/END_CREDITS.md: tk17 splits an item
// at "|" into its two LANGUAGES, and that design ships with bilingual samples. A mark already
// spoken for by a design cannot be given a second meaning by the parser above it.
//
// Nothing is required. A rundown with no marks at all is a plain list of stories, exactly as
// every ticker read before kickers existed - which is why no sample had to change.
//
// Values are escaped in tickerItemHtml() below rather than here, because a design's
// renderTickerKicked() is handed the two halves separately and must get them already safe.

// The longest text accepted BEFORE the colon as a kicker. A kicker is a tag; a headline is
// not. Without this, "The question everyone was asking was this:" becomes a tag.
var KICKER_LABEL_MAX = 32;

// tickerKickerMark(line): the index of the colon that ends the kicker, or -1 for none.
//
// The colon must be FOLLOWED BY A SPACE or by nothing at all. That is the second condition,
// and it is why this is not the credits rule verbatim: a ticker's own designs write
// "United 2:1 City" (tk13 lifts the n:n into a score chip), "Polling stations close at 20:00"
// and "Results from 21:00", and a length guard alone would have turned every one of those
// into a kicker. A tag is written with a space after its colon; a score and a clock are not.
function tickerKickerMark(line) {
  var mark = line.search(/[:;](?=\s|$)/);
  return (mark > 0 && mark <= KICKER_LABEL_MAX) ? mark : -1;
}

// tickerTag(items, label, story): one tagged line, and the kicker it leaves open. A line with
// a story after its tag is ONE story under that tag, and it closes any run above it, since it is
// the next kicker. Only a tag with nothing after it ("SPORT:") opens a run for the lines beneath,
// which is what docs/TICKERS.md promises: an inline tag never files the stories below it.
function tickerTag(items, label, story) {
  if (!story) return label;
  items.push({ kicker: label, text: story });
  return '';
}

function parseTickerItems(text) {
  var items = [];
  var open = '';                       // the kicker the following bare lines inherit

  text.split('\n').forEach(function (raw) {
    var line = raw.trim();
    if (line === '') { open = ''; return; }        // blank line closes the open kicker

    // "SPORT<TAB>United win 3-0" - an explicit separator, so no length guard applies: the
    // operator has said outright which half is which.
    var tab = line.indexOf('\t');
    if (tab > 0) {
      open = tickerTag(items, line.slice(0, tab).trim(), line.slice(tab + 1).trim());
      return;
    }

    // The colon rule: text before the colon is the kicker.
    var mark = tickerKickerMark(line);
    if (mark > 0) {
      open = tickerTag(items, line.slice(0, mark).trim(), line.slice(mark + 1).trim());
      return;
    }

    items.push({ kicker: open, text: line });
  });
  return items;
}

// tickerItemHtml(item): one parsed item as markup.
//
// renderTickerItem() keeps its ONE argument, so every design kept working when kickers
// landed. The kicker rides INSIDE the item the design draws, ahead of the story, which is
// what makes it travel with it in a marquee and stack with it in a rotator. A design that
// places the tag itself - tk18 gives it a column of its own - defines
// renderTickerKicked(kicker, text) and is handed both halves.
//
// Escaped HERE rather than in each design's builder: the builders are the part a design
// rewrites, and the safety of the strip must not depend on remembering the rule.
//
// A BUILDER IS ONLY EVER HANDED THE STORY, never markup, and the tag is placed into what it
// returns. The kicker used to be concatenated ahead of the text and the whole string passed in,
// which works only while a builder treats its argument as opaque. Six of the twenty-two do not:
// tk04, tk06, tk13, tk14, tk17 and tk22 read their argument to find a delta, a score or a
// language break, so they matched their pattern against the SPAN instead of the story. On tk14
// "Market Board" the regex took the tag's markup for an instrument and split it at the space
// inside the class attribute, and the attribute itself aired as visible text - a viewer read
// class="ticker-kicker">OMXH25 across the strip (owner walk, 2026-08-28, reproduced with the
// rundown "OMXH25: 4218.60 +1.24%"). Placing the tag afterwards, through the DOM, makes it work
// identically on every design instead of on the ones that happen not to look at their argument.
//
// FIRST CHILD OF THE ITEM the builder drew - the same position the old string form produced for
// every design that was already right (all of them wrap the story in one element), and the
// right one for the six that were not: ahead of tk14's symbol, tk13's score chip, tk17's first
// language. A design that wants the tag somewhere else still defines renderTickerKicked(kicker,
// text) and is handed both halves - tk18 gives it a column of its own.
function tickerItemHtml(item) {
  var text = escapeHtml(item.text);
  if (!item.kicker) return renderTickerItem(text);
  var kicker = escapeHtml(item.kicker);
  if (typeof renderTickerKicked === 'function') return renderTickerKicked(kicker, text);
  var host = document.createElement('div');
  host.innerHTML = renderTickerItem(text);
  var drawn = host.firstElementChild;
  // A builder that returns bare text has no item to place the tag inside; the old spelling is
  // then exactly right, and it is the only case that still concatenates.
  if (!drawn) return '<span class="ticker-kicker">' + kicker + '</span>' + host.innerHTML;
  var tag = document.createElement('span');
  tag.className = 'ticker-kicker';
  tag.textContent = item.kicker;   // textContent escapes it - the same safety, done by the DOM
  drawn.insertBefore(tag, drawn.firstChild);
  return host.innerHTML;
}

// rebuildTicker(): re-render the items from the hidden #f0 source.
//
// update() passes keepIfSame, and then an update that changes nothing the items draw (a speed
// press, a new label, or the data resent as it stands) leaves the items alone, and the answer is
// whether it re-rendered. A flip cycle tweens the .ticker-item elements themselves, so replacing
// them is something the running motion has to be told about (tickerItemsChanged), and a press
// that changes no item should not cost it a handover. play() always rebuilds, because a take must
// start from clean items. The credit rolls guard their rows the same way, in rebuildCredits().
var tickerBuiltHtml = null;
function rebuildTicker(keepIfSame) {
  var track = document.getElementById('ticker-track');
  // A ROTATING ticker shows one item at a time and the graphic's own timer advances it, so
  // rendering the whole list here would both look wrong and pile every item into the strip at
  // once. Hand it back to the rotator instead.
  if (TICKER_ROTATE && typeof tickerShowNext === 'function') { tickerShowCurrent(); return; }
  var html = '';
  parseTickerItems(document.getElementById('f0').textContent).forEach(function (item) {
    html += tickerItemHtml(item);
  });
  // The marquee loop needs the set twice: sliding one set length reads as endless.
  if (TICKER_DOUBLE_ITEMS) html += html;
  if (keepIfSame === true && html === tickerBuiltHtml) return false;
  tickerBuiltHtml = html;
  track.innerHTML = html;
  return true;
}

// Write one field value into its element. Text fields get plain
// text (operator input never runs as HTML); an <img id="fN"> gets the value as its image path.
function setFieldValue(el, value) {
  if (el.tagName === 'IMG') {
    if (value) { el.src = value; el.style.display = ''; }
    else { el.removeAttribute('src'); el.style.display = 'none'; }  // empty = show the design's placeholder
    // The img's parent gets .has-image so the CSS can hide a placeholder mark, resize, etc.
    if (el.parentNode && el.parentNode.classList) el.parentNode.classList.toggle('has-image', !!value);
  } else if (el.tagName === 'image') {
    // An SVG picture slot (an imported design's own <image> layer): swap its href. Empty
    // restores the picture the designer drew, so an untouched field changes nothing.
    if (!el.hasAttribute('data-orig-href')) el.setAttribute('data-orig-href', el.getAttribute('href') || '');
    el.setAttribute('href', value || el.getAttribute('data-orig-href'));
  } else {
    el.textContent = value;
  }
}

// update(data): SPX sends field values as JSON; the label (f1) is written straight into
// its element, the items (f0) into the hidden source, and the track re-renders only if the
// items it draws changed (see rebuildTicker). New items reach a strip that is already running,
// from a flip's next item boundary or from where a marquee stands, rather than waiting for a take.
function update(data) {
  var fields = (typeof data === 'string') ? JSON.parse(data) : data;
  for (var key in fields) {
    var el = document.getElementById(key);
    if (el) setFieldValue(el, fields[key]);
  }
  var itemsChanged = rebuildTicker(true);
  // A new SPEED reaches a strip that is already travelling, rather than waiting for the next
  // take. The dashboard's ± live-number buttons send exactly this update and say they act on
  // air, so the field has to mean it (see tickerApplySpeed). It goes first, so a story still
  // finishing its turn after the new items arrive in the same update finishes at the new pace.
  tickerApplySpeed();
  if (itemsChanged) tickerItemsChanged();
}

// play(): rebuild (fresh measurements), then start the loop.
function play() {
  gsap.killTweensOf('*');
  tickerMotionEnd();
  rebuildTicker();
  buildInTimeline();
}

// stop(): take the ticker off air (also stops the loop).
function stop() {
  gsap.killTweensOf('*');
  tickerMotionEnd();
  buildOutTimeline();
}

// next(): SPX Continue — advance one step along the default path. This design ships
// single-step, so it normally does nothing; it still funnels to the interpreter so a
// template that GROWS a step (or a state machine) stays drivable through the SPX contract.
function next() {
  return (typeof revealNextStep === 'function') ? revealNextStep() : null;
}

// Render once on load so the preview shows content before the first update().
// This file loads in <head>, before the ticker elements exist — wait for the DOM.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', rebuildTicker);
} else {
  rebuildTicker();                // DOM already parsed (e.g. an inline preview build)
}

// Marquee designs render the items twice for a seamless loop; flip designs don't.
var TICKER_DOUBLE_ITEMS = true;

// A ROTATING ticker shows one item at a time, advanced by the graphic's state machine rather
// than by endless motion — so the whole list never goes into the strip at once.
var TICKER_ROTATE = false;

// renderTickerItem(text): one item followed by a small dim dot separator.
function renderTickerItem(text) {
  return '<span class="ticker-item">' + text + '</span>' +
         '<span class="ticker-sep">\u2022</span>';
}

// ---- Measured motion (the animation data references these by name) ----
// motionSpeed(): the template's speed knob. The NOACG_ANIM data block owns it; a legacy
// animSpeed variable is honored too, and hand-written animation code defaults to 1.
function motionSpeed() {
  if (typeof NOACG_ANIM !== 'undefined' && NOACG_ANIM.speed) return NOACG_ANIM.speed;
  if (typeof animSpeed !== 'undefined' && animSpeed) return animSpeed;
  return 1;
}

// tickerSpeed(): the OPERATOR's speed, read from the "f2" field on the control
// page. It is a PERCENTAGE of the pace this design ships at, so 100 is exactly the authored
// speed, 150 is half again as fast and 60 is a slow, readable crawl. Input only: the value
// lives in a hidden holder and is never drawn.
//
// Blank, non-numeric and zero all mean "as designed" rather than "stop": a strip frozen
// mid-word because someone typed 0 is a graphic stuck on air, and the clamp below is what
// keeps that from being one keystroke away.
function tickerSpeed() {
  var el = document.getElementById('f2');
  var percent = el ? parseFloat(el.textContent) : NaN;
  if (!isFinite(percent) || percent <= 0) return 1;      // blank or nonsense: the design's own speed
  return Math.min(400, Math.max(10, percent)) / 100;     // 10%–400%, so the strip always moves
}

// The live pace: the design's authored speed multiplied by the operator's percentage. Both
// builders read this one function, so the two knobs can never disagree.
function tickerMotionSpeed() {
  return motionSpeed() * tickerSpeed();
}

// The running travel or cycle, and the speed it was built at. Both builders below set them, so
// tickerApplySpeed() can reach whichever one is live.
var tickerMotionLive = null;
var tickerMotionBuiltAt = 1;
// A flip story kept on screen after an edit until its turn ends (see tickerFlipHandover).
var tickerLeftover = null;

// tickerApplySpeed(): make a speed change land on a strip that is ALREADY RUNNING.
//
// Both builders below measure once, at play(), because that is when the operator's text has a
// width. So a new speed arriving through update() would otherwise sit in the holder and change
// nothing until the next take, and the surfaces an operator actually uses promise better than
// that. The production dashboard's "± LIVE NUMBERS act on air" row picks up every number field
// a graphic has, this one included, and says one press changes the figure on the live graphic.
//
// A timeScale is what makes that true without a seam. Restarting the tween would honour the
// number and snap a half-scrolled strip back to its start, which is worse than ignoring it;
// scaling the running tween changes the pace from this frame on, from where the strip is.
// The ratio is against the speed the tween was BUILT at, so repeated changes compose correctly
// rather than each one measuring from the design's own rate.
//
// The builder's tween sits INSIDE the step's timeline, which has no smoothChildTiming, and
// without it GSAP jumps the child to where the new pace would have had it (287px on tk01 at
// 300%). The flag is lent for the one call - but only to a PLAYING parent: on a paused one (a
// settled preview, an editor scrub) GSAP answers a slow-down by moving the parent's start to
// -Infinity, so a paused strip takes the plain timeScale and the next seek shows it. The
// credit rolls do the same in creditsApplySpeed().
function tickerApplySpeed() {
  var live = tickerMotionLive;
  if (!live || !tickerMotionBuiltAt) return;
  var scale = tickerMotionSpeed() / tickerMotionBuiltAt;
  var parent = live.parent;
  if (!parent || parent.paused()) { live.timeScale(scale); return; }
  var smooth = parent.smoothChildTiming;
  parent.smoothChildTiming = true;
  live.timeScale(scale);
  parent.smoothChildTiming = smooth;
}

// tickerShowNext(): the ROTATOR's beat — put the next item in the track, on its own.
//
// This is deliberately NOT measured motion. A marquee's travel has to be measured because its
// distance depends on the text; showing one item at a time does not — the movement is a fixed
// slide the timeline keyframes, and all this does is swap what the slot contains. That matters
// beyond tidiness: a state whose timeline never ends can never arm a timer (a call scheduled
// at the timeline's end never fires), so a machine-driven cycle cannot use endless motion.
// Advancing the index in a plain call, which adds no duration at all, is what lets the beat be
// a real timer transition.
var tickerIndex = 0;              // which item is showing (runtime data, never a state)

// The SAME parse the marquee runs (parseTickerItems, in the shared runtime above), so a
// kicker means the same thing whichever motion preset the design ships with. Reading the raw
// lines here instead is what would make "SPORT:" a story of its own in a rotating strip.
function tickerItems() {
  var source = document.getElementById('f0');
  if (!source) return [];
  return parseTickerItems(source.textContent);
}

function tickerShowNext() {
  tickerIndex = tickerIndex + 1;
  tickerShowCurrent();
}

// tickerShowCurrent(): put the CURRENT item in the slot without advancing — what a data
// update needs, so re-typing the items does not skip one.
function tickerShowCurrent() {
  var items = tickerItems();
  var track = document.getElementById('ticker-track');
  if (!track || items.length === 0) return;
  // tickerItemHtml() for the same reason rebuildTicker() uses it: it is where the item's two
  // halves are escaped, and where a design's own kicker markup is offered the chance to run.
  track.innerHTML = tickerItemHtml(items[tickerIndex % items.length]);
}

// tickerMarquee(): the classic endless travel. The track holds the items TWICE, so sliding
// exactly one set width and repeating reads as seamless — and the width is measured here,
// at play() time, because it depends on how much text the operator typed.
function tickerMarquee(target) {
  var track = document.querySelector(target);
  if (!track) return null;
  tickerTakeStart();
  var oneSetWidth = track.scrollWidth / 2;        // the items are rendered twice
  if (oneSetWidth <= 0) return null;            // nothing to scroll yet
  tickerMotionLive = tickerMarqueeLoop(track, oneSetWidth);
  return tickerMotionLive;
}

// tickerMarqueeLoop(): one set width of travel, repeated forever.
function tickerMarqueeLoop(track, oneSetWidth) {
  // Travel speed. Edit the 140 to change what this design ships at; the operator's percentage
  // multiplies it, and a later change to that percentage reaches this tween through
  // tickerApplySpeed() rather than waiting for the next take.
  var speed = tickerMotionSpeed();
  var pixelsPerSecond = 140 * speed;
  var travel = gsap.fromTo(track,
    { x: 0 },
    {
      x: -oneSetWidth,                          // one full set = a perfect loop point
      duration: oneSetWidth / pixelsPerSecond,
      ease: 'none',                             // constant speed — never eased
      repeat: -1,                               // loop until stop()
    }
  );
  // What tickerItemsChanged() reads when the items change with the strip running.
  travel.noacgTicker = { kind: 'marquee', track: track, width: oneSetWidth, pixelsPerSecond: pixelsPerSecond };
  tickerMotionBuiltAt = speed;
  return travel;
}

// tickerFlipCycle(): items take turns — flip up in, hold long enough to read, flip out.
// One segment PER ITEM, so the sequence's length is the operator's line count: a content-
// driven shape, which is the other thing keyframes can't express.
function tickerFlipCycle(target) {
  var track = document.querySelector(target);
  if (!track) return null;
  tickerTakeStart();
  var items = Array.prototype.slice.call(track.querySelectorAll('.ticker-item'));
  if (!items.length) return null;
  tickerMotionLive = tickerFlipLoop(track, items, 0);
  return tickerMotionLive;
}

// tickerFlipLoop(): the endless rotation, starting at item number `first` of the list.
function tickerFlipLoop(track, items, first) {
  // The hold IS this design's speed: nothing travels, so what an operator turns up is how
  // long each item stays. The flips either side of it scale with it, exactly as the credits'
  // paged preset does, so a faster strip is faster all through rather than snappy and patient.
  var speed = tickerMotionSpeed();
  var holdSeconds = 3.2 / speed;                // reading time per item
  var order = [];                               // list positions, in the order they show
  for (var k = 0; k < items.length; k++) order.push((first + k) % items.length);

  var cycle = gsap.timeline({ repeat: -1 });    // the endless item rotation
  cycle.set(items, { opacity: 0 }, 0);          // all items start hidden
  order.forEach(function (index) {
    var item = items[index];
    cycle.fromTo(item, { y: 18, opacity: 0 }, { y: 0, opacity: 1, duration: 0.4 / speed, ease: 'power3.out' });
    cycle.to(item, { y: -18, opacity: 0, duration: 0.35 / speed, ease: 'power2.in' }, '+=' + holdSeconds);
  });
  // What tickerItemsChanged() reads to find the item on screen. `lead` is how long a story from
  // before an edit still has on screen before the cycle starts: none, when a take built it.
  cycle.noacgTicker = { kind: 'flip', track: track, cycle: cycle, items: items, order: order, lead: 0 };
  tickerMotionBuiltAt = speed;
  return cycle;
}

// tickerItemsChanged(): new ITEMS reach a strip that is already running.
//
// update() calls this when it has just re-rendered the track. Both builders measured at play(),
// so without it the running motion kept working on what it measured then. A flip cycle went on
// fading the old item nodes, which were gone, and the strip was blank until the next take
// (measured on tk03 in Chromium: 1 item visible before an update, 0 in every sample for 20 s
// after it). A marquee went on sliding the OLD set width, so with a list of another length its
// loop point no longer landed on the second copy and the strip jumped once a loop (888 px on
// tk01).
//
// So the running motion is swapped for a HANDOVER built on the new items, from where the strip
// is. It goes into the same parent at the parent's current time, so nothing before it moves, and
// it becomes the live motion, so a speed press or a second edit reaches it the same way. An edit
// during the entrance, before the motion has begun, rebuilds it where it was going to start. An
// emptied list leaves an empty handover in place, so the stories typed next still reach it.
function tickerItemsChanged() {
  var live = tickerMotionLive;
  if (!live || !tickerOnAir(live)) return;      // nothing on air: the next take builds fresh
  var parent = live.parent, begun = parent.time() >= live.startTime();
  var at = begun ? parent.time() : live.startTime();
  if (live.noacgTicker.kind === 'flip') tickerFlipHandover(live, parent, at, begun);
  else tickerMarqueeHandover(live, parent, at, begun);
}

// On air means still reachable from GSAP's root. Another entrance path (the simulator, a snap,
// a render) can kill the step this motion sits in, and an edit must not build on that.
function tickerOnAir(motion) {
  while (motion.parent) motion = motion.parent;
  return motion === gsap.globalTimeline;
}

// The handover takes the old motion's place: the same parent, the live handle, today's pace.
// With no items left it still has to run forever, as the loop it replaces did: a step whose
// children all end completes, GSAP's root lets it go, and the stories typed next reach nothing.
function tickerHandoverPlace(parent, handover, at, loop) {
  if (!loop) {
    handover.to({}, { duration: 1, repeat: -1 }, handover.duration());
    tickerMotionBuiltAt = tickerMotionSpeed();  // a loop sets this itself when it is built
  }
  parent.add(handover, at);
  tickerMotionLive = handover;
}

// A marquee keeps its PICTURE: the offset into one set of the old items is where the same
// stories stand in the new track, since an edit rarely moves the ones already passing. It
// travels to the end of the new set and the endless loop starts there, a whole new set wide,
// so the loop point lands on the second copy again.
function tickerMarqueeHandover(live, parent, at, begun) {
  var info = live.noacgTicker, track = info.track;
  var into = begun && info.width ? (((-gsap.getProperty(track, 'x')) % info.width) + info.width) % info.width : 0;
  live.kill();
  var oneSetWidth = track.scrollWidth / 2;
  var handover = gsap.timeline(), loop = null;
  if (oneSetWidth > 0) {
    into = into % oneSetWidth;                  // a shorter list can end before the picture
    loop = tickerMarqueeLoop(track, oneSetWidth);
    handover.fromTo(track, { x: -into }, {
      x: -oneSetWidth, duration: (oneSetWidth - into) / loop.noacgTicker.pixelsPerSecond, ease: 'none',
    });
    handover.add(loop);
  } else {
    gsap.set(track, { x: 0 });                  // every item removed
  }
  handover.noacgTicker = loop ? loop.noacgTicker : { kind: 'marquee', track: track, width: 0 };
  tickerHandoverPlace(parent, handover, at, loop);
}

// A flip lets the story on screen FINISH: it stays for the rest of its hold and flips out on
// time, and the new list starts at that boundary (tickerFlipNext says with which story).
function tickerFlipHandover(live, parent, at, begun) {
  var info = live.noacgTicker, track = info.track;
  var showing = begun ? tickerFlipShowing(live) : null;
  var items = Array.prototype.slice.call(track.querySelectorAll('.ticker-item'));
  var handover = gsap.timeline(), lead = 0, loop = null;
  if (showing) {
    // The rest of its turn is played off the motion that was running it, so it eases out exactly
    // as it was going to, at the pace it was running. That is the old cycle, or, when the story
    // was already finishing after an earlier edit, the same cycle that edit kept: handovers do
    // not nest, however fast the edits come.
    var source = showing.source;
    if (source === live) { live.pause(); parent.remove(live); } else live.kill();
    var rest = source.tweenFromTo(showing.from, showing.to, { duration: showing.left });
    handover.add(rest, 0);
    lead = showing.left;
    var item = showing.item;
    track.insertBefore(item, track.firstChild);   // the story on screen stays until its turn ends
    tickerLeftover = item;
    handover.call(function () {
      if (item.parentNode) item.parentNode.removeChild(item);
      if (tickerLeftover === item) tickerLeftover = null;
      handover.noacgTicker.leadItem = null;
      rest.kill(); source.kill();               // let the old motion and its story go
      rest = source = item = null;
    }, null, lead);
  } else {
    live.kill();
  }
  if (items.length) {
    gsap.set(items, { opacity: 0 });            // the new items wait for their turn
    loop = tickerFlipLoop(track, items, tickerFlipNext(showing, items, info.items));
    handover.add(loop, lead);
  }
  handover.noacgTicker = {
    kind: 'flip', track: track, cycle: loop, items: items, order: loop ? loop.noacgTicker.order : [],
    lead: lead, leadItem: showing && showing.item, leadPosition: showing && showing.position,
    restOf: showing && showing.source, restTo: showing && showing.to,
  };
  tickerHandoverPlace(parent, handover, at, loop);
}

// The story on a flip's screen now and where it sits in its list, with the rest of its turn:
// the motion that runs it, the span of that motion left, and how long that takes on air. Null
// when nothing is showing (the list was emptied).
function tickerFlipShowing(live) {
  var info = live.noacgTicker, now = live.time();
  if (now < info.lead) {                        // still finishing a story from an earlier edit
    return { item: info.leadItem, position: info.leadPosition, source: info.restOf,
      from: info.restOf.time(), to: info.restTo, left: (info.lead - now) / live.timeScale() };
  }
  if (!info.cycle) return null;
  var turn = info.cycle.duration() / info.order.length, into = info.cycle.time();
  var k = Math.min(info.order.length - 1, Math.floor(into / turn));
  var ends = now + (k + 1) * turn - into;
  return { item: info.items[info.order[k]], position: info.order[k], source: live,
    from: now, to: ends, left: (ends - now) / live.timeScale() };
}

// Which story of the new list comes next: the one after the story on screen, found by its text
// (the copy nearest its old place, if it appears twice), so a story added above it does not
// make the strip repeat itself. Not found, it was edited in place and the one after its old
// place comes next - unless no story of the old list is left, and a new list starts at its top.
function tickerFlipNext(showing, items, before) {
  if (!showing) return 0;
  var texts = items.map(function (item) { return item.textContent; });
  var found = -1;
  for (var i = 0; i < texts.length; i++) {
    if (texts[i] !== showing.item.textContent) continue;
    if (found < 0 || Math.abs(i - showing.position) < Math.abs(found - showing.position)) found = i;
  }
  if (found >= 0) return (found + 1) % items.length;
  var kept = before.some(function (item) { return texts.indexOf(item.textContent) >= 0; });
  return kept ? (showing.position + 1) % items.length : 0;
}

// tickerTakeStart(): a take starts from clean items. A story an edit was still finishing when
// the strip was stopped goes (play() re-renders the track anyway; an entrance that skips play()
// does not), and the handle lets go of the last take's motion.
function tickerTakeStart() {
  if (tickerLeftover && tickerLeftover.parentNode) tickerLeftover.parentNode.removeChild(tickerLeftover);
  tickerLeftover = null;
  tickerMotionLive = null;
}

// tickerMotionEnd(): stop the running motion. A strip taken off air has nothing left for an
// edit to reach. A story still finishing its turn stays where it is, for the strip's fade.
function tickerMotionEnd() {
  if (tickerMotionLive) tickerMotionLive.kill();
  tickerMotionLive = null;
}

/* == ANIMATION (generated — the Animation panel rewrites this block) == */
// The graphic's animation as DATA. Steps play in order — the first on ▶ play(), each
// middle step on one » next() press (SPX Continue), the last on ■ stop(). Each layer's
// properties are keyframe lists on the step's local clock: { "time", "value", "ease" }.
// "reveals" names the layers that first become visible in that step; "hides" names the
// layers that leave in it; "calls" fires named template functions (a clock engine's
// startClock/stopClock) at their moment on the step's clock; "loops" makes a layer's track
// repeat (repeat -1 = forever, yoyo = breathe back and forth); "dynamics" adds MEASURED
// motion — a named builder function (defined below, outside this block) reads the DOM and
// returns the tween, which is how a marquee travels exactly one track-width no matter how
// much text the operator types. An optional "machine" adds a STATE GRAPH over the steps:
// parallel groups of states (each state's content is a timeline — the steps are the default
// path's, in order), transitions fired by operator events (noacgDispatch) or timers, and
// instant snap to any state (noacgSnap). Without it the steps ARE the machine: a linear
// walk driven by play/next/stop. The timeline UI reads and writes this block — and so can
// you: edit a number and press play.
var NOACG_ANIM = {
  "version": 2,
  "root": ".ticker",
  "speed": 1,
  "steps": [
    {
      "name": "Enter",
      "duration": 0.5,
      "ease": "power2.out",
      "dynamics": [
        { "time": 0.5, "build": "tickerMarquee", "target": "#ticker-track" }
      ],
      "layers": {
        ".ticker-box": {
          "opacity": [
            { "time": 0, "value": 0 },
            { "time": 0.5, "value": 1 }
          ]
        }
      }
    },
    {
      "name": "Out",
      "duration": 0.4,
      "ease": "power2.in",
      "layers": {
        ".ticker-box": {
          "opacity": [
            { "time": 0, "value": 1 },
            { "time": 0.4, "value": 0 }
          ]
        }
      }
    }
  ]
};

// ---- The interpreter (the same in every template — edit the DATA above instead) ----
// Steps play on the operator's cues: steps[0] on play(), each middle step on one next()
// press, the last step on stop(). Keyframe times sit on the step's local clock and are
// divided by the speed knob. A keyframe's ease is the ease INTO it (default: the step's).
// When the data carries a "machine", the same cues drive its default path, and the state
// engine below adds operator events (noacgDispatch), timers, and instant snap (noacgSnap).
// ---- Eases (shared with the editor, which samples, splits and reverses keys with this code) ----
// Capability: shared-ease-v2. noacgEase(text) returns the curve E(p) of an ease string, or null
// when the string is outside this grammar; the interpreter then hands the string to GSAP as it
// always did. A recognized ease reaches GSAP as this function, never as a string it could replace
// with its default.
//   none | linear, power0-4, quad, cubic, quart, quint, strong, sine, expo, circ, bounce, back(s)
//   or elastic(a, p), each with .in, .out or .inOut (bare means .out) | steps(n) | steps(n, true)
//   | cubic-bezier(x1, y1, x2, y2) with x1 and x2 in 0..1
//   | slice(ease, a, b): that ease between a and b, rescaled to run from 0 to 1
//   | hold: keep the departing key's value, then jump to the arriving key's (a Hold keyframe)
//   | jump: jump to the arriving key's value at once, then keep it (a Hold played backwards).
// Named curves repeat GSAP 3.15's formulas in its operation order, so they match it exactly.
var noacgEaseCache = {};
// GSAP rounds timeline times to 1e-7 s, so at a key's exact time the segment arriving there can
// read 0.9999987 rather than 1. A hold jumps in the last 1e-5 of its segment, which that rounding
// still reaches for any segment of 10 ms or more, and a jump mirrors it at the start.
var NOACG_EASE_EDGE = 1e-5;
var NOACG_EASE_POWER = { linear: 1, power0: 1, quad: 2, power1: 2, cubic: 3, power2: 3, quart: 4, power3: 4, quint: 5, power4: 5, strong: 5 };
var NOACG_EASE_SHAPED = { sine: 1, expo: 1, circ: 1, bounce: 1, back: 1, elastic: 1 };
var NOACG_EASE_TWO_PI = 2 * Math.PI;
function noacgEaseHas(map, name) { return Object.prototype.hasOwnProperty.call(map, name); }
function noacgEaseNumber(text) {
  return /^\s*[-+]?(\d+\.?\d*|\.\d+)(e[-+]?\d+)?\s*$/i.test(text) ? Number(text) : NaN;
}
// An argument list split on its top-level commas: a slice carries a whole ease inside it.
function noacgEaseArgs(text) {
  var parts = [], depth = 0, from = 0;
  for (var i = 0; i < text.length; i++) {
    var c = text.charAt(i);
    if (c === '(') depth++;
    else if (c === ')') depth--;
    else if (c === ',' && depth === 0) { parts.push(text.slice(from, i)); from = i + 1; }
  }
  parts.push(text.slice(from));
  return parts;
}

// Describe an ease string, or return null. The text itself is never rewritten.
function noacgEaseParse(text) {
  if (typeof text !== 'string') return null;
  if (text === 'none') return { kind: 'none', text: text };
  var m = /^([a-z][a-z0-9]*(?:-[a-z]+)?)(?:\.(in|out|inOut))?(?:\((.*)\))?$/.exec(text);
  if (!m) return null;
  var name = m[1], side = m[2], called = m[3] !== undefined, args = called ? noacgEaseArgs(m[3]) : [], values = [], i;
  for (i = 0; i < args.length; i++) values.push(noacgEaseNumber(args[i]));
  if (noacgEaseHas(NOACG_EASE_POWER, name) || noacgEaseHas(NOACG_EASE_SHAPED, name)) {
    var most = name === 'back' ? 1 : name === 'elastic' ? 2 : 0;
    if (called && (args.length > most || values.some(function (v) { return !isFinite(v); }))) return null;
    return { kind: 'family', text: text, name: name, side: side || 'out', args: called ? values : [], argText: called ? '(' + m[3] + ')' : '' };
  }
  if ((name === 'hold' || name === 'jump') && !side && !called) return { kind: name, text: text };
  if (side || !called) return null;
  if (name === 'steps' && args.length <= 2) {
    var count = values[0];
    if (!(count >= 1 && count === Math.floor(count))) return null;
    if (args.length === 2 && args[1].replace(/^\s+|\s+$/g, '') !== 'true') return null;
    return { kind: 'steps', text: text, count: count, start: args.length === 2 };
  }
  if (name === 'cubic-bezier' && args.length === 4) {
    if (values.some(function (v) { return !isFinite(v); })) return null;
    // x1 and x2 inside 0..1 keep time monotonic, so every moment has one value.
    if (!(values[0] >= 0 && values[0] <= 1 && values[2] >= 0 && values[2] <= 1)) return null;
    return { kind: 'bezier', text: text, x1: values[0], y1: values[1], x2: values[2], y2: values[3] };
  }
